CREATE TABLE "schedules" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "schedule_id" character varying NOT NULL, "name" character varying NOT NULL, "description" character varying NULL, "enabled" boolean NOT NULL DEFAULT true, "rrule" character varying NOT NULL, "exclusions" jsonb NULL, "timezone" character varying NOT NULL DEFAULT 'UTC', "dtstart" timestamptz NOT NULL, "dtend" timestamptz NULL, "next_run" timestamptz NULL, "last_fired" timestamptz NULL, "organization_schedules" bigint NOT NULL, "schedule_saved_config" bigint NULL, "template_schedules" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "schedules_organizations_schedules" FOREIGN KEY ("organization_schedules") REFERENCES "organizations" ("id") ON DELETE NO ACTION, CONSTRAINT "schedules_saved_launch_configs_saved_config" FOREIGN KEY ("schedule_saved_config") REFERENCES "saved_launch_configs" ("id") ON DELETE SET NULL, CONSTRAINT "schedules_templates_schedules" FOREIGN KEY ("template_schedules") REFERENCES "templates" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "schedules_schedule_id_key" ON "schedules" ("schedule_id");
CREATE UNIQUE INDEX "schedule_name_organization_schedules" ON "schedules" ("name", "organization_schedules");
CREATE INDEX "schedule_enabled_next_run_schedule_id" ON "schedules" ("enabled", "next_run", "schedule_id");
CREATE TABLE "schedule_occurrences" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "occurrence_at" timestamptz NOT NULL, "outcome" character varying NOT NULL DEFAULT 'claimed', "reason" character varying NULL, "suppressed_count" bigint NOT NULL DEFAULT 0, "job_id" character varying NULL, "schedule_occurrences" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "schedule_occurrences_schedules_occurrences" FOREIGN KEY ("schedule_occurrences") REFERENCES "schedules" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "scheduleoccurrence_occurrence_at_schedule_occurrences" ON "schedule_occurrences" ("occurrence_at", "schedule_occurrences");
CREATE INDEX "scheduleoccurrence_schedule_occurrences" ON "schedule_occurrences" ("schedule_occurrences");
